    <script>
        const nav=document.getElementById('nav'),menu=document.getElementById('menu');addEventListener('scroll',()=>nav.classList.toggle('scrolled',scrollY>35),{passive:true});menu.addEventListener('click',()=>nav.classList.toggle('open'));document.querySelectorAll('.nav-links a').forEach(a=>a.addEventListener('click',()=>nav.classList.remove('open')));
        const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
        if(!matchMedia('(prefers-reduced-motion: reduce)').matches){addEventListener('mousemove',e=>{const phone=document.querySelector('.phone');if(phone&&innerWidth>980){const x=(e.clientX/innerWidth-.5)*8,y=(e.clientY/innerHeight-.5)*8;phone.style.marginLeft=x+'px';phone.style.marginTop=y+'px'}},{passive:true})}
    </script>
